<?php require_once '../config.php';require_admin();if($_SERVER['REQUEST_METHOD']==='POST'){foreach(['site_name','hero_title','hero_text','phone','whatsapp','email','about'] as $k)set_setting($k,$_POST[$k]??'');header('Location: settings.php?saved=1');exit;}?><!doctype html><html lang="tr"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width"><link rel="stylesheet" href="../assets/style.css"></head><body><div class="adminwrap"><a href="dashboard.php">← Dashboard</a><h1>Site Ayarları</h1><?php if(isset($_GET['saved']))echo '<p class="gold">Kaydedildi.</p>';?><form class="admin" method="post"><input name="site_name" value="<?=e(setting('site_name'))?>" placeholder="Site adı"><input name="hero_title" value="<?=e(setting('hero_title'))?>" placeholder="Hero başlık"><textarea name="hero_text" placeholder="Hero açıklama"><?=e(setting('hero_text'))?></textarea><input name="phone" value="<?=e(setting('phone'))?>" placeholder="Telefon"><input name="whatsapp" value="<?=e(setting('whatsapp'))?>" placeholder="WhatsApp numarası"><input name="email" value="<?=e(setting('email'))?>" placeholder="E-posta"><textarea name="about" rows="8" placeholder="Hakkımızda"><?=e(setting('about'))?></textarea><button class="btn">Ayarları Kaydet</button></form></div></body></html>
